Currently, we have some deeply nested fields that we want to filter on.   SearchBox filters are convenient, and so is Query.toESQuery(), however there doesn't appear to be a straightforward way to translate keys within the SearchBox into real elasticsearch keys.    Doing so allows us to define a sort of DSL for the user

e.g., 
```

export const queryKeyTranslations: QueryKeyTranslation[] = [
  {
    userKey: 'type',
    realKey: 'metadata.verificationData.diagnosticFile.type',
  },
  {
    userKey: 'source',
    realKey: 'metadata.verificationData.diagnosticFile.source.source',
  },
  {
    userKey: 'case',
    realKey: 'metadata.verificationData.customerData.caseNumber',
  },
];
```

```
export interface QueryKeyTranslation {
  userKey: string;
  realKey: string;
}

export const queryKeyTransform = (
  query: Query,
  translations: QueryKeyTranslation[]
) => {
  for (const translation of translations) {
    const simpleValues = query.getSimpleFieldClause(translation.userKey)?.value;
    query = query.removeSimpleFieldClauses(translation.userKey);
    if (simpleValues) {
      if (Array.isArray(simpleValues)) {
        for (const value of simpleValues) {
          query = query.addSimpleFieldValue(translation.realKey, value);
        }
      } else {
        query = query.addSimpleFieldValue(translation.realKey, simpleValues);
      }
    }

    const orValues = query.getOrFieldClause(translation.userKey)?.value;
    query = query.removeOrFieldClauses(translation.userKey);
    if (orValues) {
      if (Array.isArray(orValues)) {
        for (const value of orValues) {
          query = query.addOrFieldValue(translation.realKey, value);
        }
      } else {
        query = query.addOrFieldValue(translation.realKey, orValues);
      }
    }

    const isValue = query.getIsClause(translation.userKey);
    query = query.removeIsClause(translation.userKey);
    if (isValue) {
      if (isValue.match === 'must') {
        query = query.addMustIsClause(translation.realKey);
      } else {
        query = query.addMustNotIsClause(translation.realKey);
      }
    }
  }
};
```

