      ".../node_modules/@elastic/apm-rum-core/node_modules/stackframe/package.json": 1689369687854,
      ".../node_modules/@elastic/apm-rum-core/package.json": 1689369687355,
      ".../node_modules/@elastic/apm-rum/package.json": 1689369687118,
