`deep-freeze-strict` is a JavaScript library that provides a way to freeze JavaScript objects and prevent any modifications to them. It works by recursively freezing all nested objects, making them read-only and immutable.

We wish to drop the usage of libraries like deep-freeze-strict in favor of more performant native implementations.

Current usage of `deep-freeze-strict` is in `opensearch_dashboards_utils` plugin in `src/plugins/opensearch_dashboards_utils/common/state_containers/create_state_container.ts`. 

```
import deepFreeze from 'deep-freeze-strict';

const defaultFreeze: <T>(value: T) => T = isProduction
  ? <T>(value: T) => value as T
  : <T>(value: T): T => {
      const isFreezable = value !== null && typeof value === 'object';
      if (isFreezable) return deepFreeze(value) as T;
      return value as T;
    };
```

This `defaultFreeze` function is used to freeze states. When creating a state container, if no other `freeze()` function is provided, then the `defaultFreeze()` will be used as default.

Since for #3660 we need to identify and list all usage cases of lodash functions, I decided to write a script that helped me find and list all lodash functions which can be found in the repo.

Here is the code. You are welcome to use and modify this script, as it may be needed to replace other packages.

```python
import os
import re

def search_directory(directory_path, search_string):
    excluded_dirs = {"node_modules"}  # Directories to exclude from the search
    result = []
    for root, dirs, files in os.walk(directory_path):
        # Exclude directories that match any of the excluded directories
        dirs[:] = [d for d in dirs if d not in excluded_dirs]
        files[:] = [f for f in files if f.endswith(('.ts', '.js', '.tsx', 'jsx'))]
        for file_name in files:
            file_path = os.path.join(root, file_name)
            with open(file_path, "r") as f:
                for line_num, line in enumerate(f, start=1):
                    if search_string in line:
                        result.append(file_path)
    return result


def search_files(files, search_str):
    result = []
    for file in files:
        with open(file, 'r') as f:
            for line_num, line in enumerate(f, start=1):
                if search_str in line:
                    result.append(line.strip())
    return result

def print_lines(files, search_str):
    separator = "=" * 20
    for file in files:
        print("Found in {0}: ".format(file))
        with open(file, 'r') as f:
            for line_num, line in enumerate(f, start=1):
                if search_str in line:
                    print("line {0}:{1}".format(line_num, line.strip()))
        print(separator)


def extract_pattern(lines_with_function, regexp_pattern):
    function_set = []
    for line in lines_with_function:
        function_set += re.findall(regexp_pattern, line)
    return list(set(function_set))

def flatten(lst):
    return [item for sublist in lst for item in sublist]

if __name__ == '__main__':
    files_with_lodash = search_directory("./OpenSearch-Dashboards", "'lodash'")

    # find functions that start with _.
    lines_with_function = search_files(files_with_lodash, "_.")
    lodash_methods = extract_pattern(lines_with_function, r"_\.\w+")
    function_subset_1 = set([method for method in lodash_methods])

    # find functions from named imports
    import_lines = search_files(files_with_lodash, "from 'lodash'")
    raw_file_names = extract_pattern(import_lines, r"{.*}")
    function_names = flatten([names[1:-1].split(",") for names in raw_file_names])
    function_subset_2 = set([name.strip() for name in function_names])
    
    final_function_set = sorted(list(function_subset_2.union(function_subset_1)))
    for f in final_function_set:
        print(f)
```

